// Writes compile_cases_test.go: the templates of cases.mjs compiled by edge.js 6.5.1
// on Node 24 the way Compiler.compileRaw does it, in sync and/or async mode:
//
//	node record_cases.mjs | gofmt > ../compile_cases_test.go   (original at /opt/original)
import { createRequire } from 'node:module'
import { Edge, EdgeError } from '/opt/original/build/index.js'
import { migrate } from '/opt/original/build/src/migrate/plugin.js'
import { cases } from './cases.mjs'
import { goStr } from './golit.mjs'

const FILE = 'views\\users/list.edge'
const require = createRequire(import.meta.url)
const stringify = require('/opt/original/node_modules/js-stringify/index.js')
const PRE = ['let out = "";', 'let $lineNumber = 1;', `let $filename = ${stringify(FILE)};`, 'try {']
const POST = ['} catch (error) {', 'template.reThrow(error, $filename, $lineNumber);', '}', 'return out;']
// claimTag of the cases marked 'c' (claimXTags in compile_test.go).
function claim(name) {
  if (/^x[A-Z]/.test(name)) return { seekable: true, block: true }
  return null
}


function line(s) {
  let raw = s.isWellFormed()
  for (const ch of s) { const c = ch.codePointAt(0); if (c === 0x60 || c < 0x20 || c === 0x7f || c === 0x2028 || c === 0x2029 || c === 0xfeff) raw = false }
  return raw ? '`' + s + '`' : goStr(s)
}

const rows = []
for (const [name, src, modes] of cases) {
  const asyncs = modes.includes('a') ? (modes.includes('s') ? [false, true] : [true]) : [false]
  for (const async of asyncs) {
    const edge = Edge.create()
    // The migrate plugin registers its tags; layouts are merged by the compiler, not
    // by the tags, so compat mode is turned off again.
    if (modes.includes('m')) { migrate(edge); edge.compiler.compat = false; edge.asyncCompiler.compat = false }
    const compiler = async ? edge.asyncCompiler : edge.compiler
    if (modes.includes('c')) compiler.claimTag(claim)
    let compiled = null
    edge.processor.process('compiled', ({ compiled: c }) => { compiled = c })
    let err = null
    try { compiler.compileRaw(src, FILE) } catch (e) {
      // A compiled body V8 cannot turn into a function is still recorded.
      if (compiled !== null) {} else if (e instanceof EdgeError) {
        if (e.filename !== FILE || typeof e.line !== 'number' || typeof e.col !== 'number') throw new Error('unexpected error fields ' + name)
        err = `${e.code} ${e.line}:${e.col} ${e.message}`
      } else err = `${e.name}: ${e.message}`
    }
    let out = `\t{\n\t\tname: ${goStr(name)},\n\t\tsrc:  ${goStr(src)},\n`
    if (async) out += '\t\tasync: true,\n'
    if (modes.includes('m')) out += '\t\tmigrate: true,\n'
    if (modes.includes('c')) out += '\t\tclaim: true,\n'
    if (err !== null) out += `\t\terr: ${goStr(err)},\n`
    else {
      const lines = compiled.replace(/stack_[A-Za-z0-9_]+/g, 'stack_ID').split('\n')
      const pre = lines.slice(0, 4), post = lines.slice(-4)
      if (pre.join('\n') !== PRE.join('\n') || post.join('\n') !== POST.join('\n')) throw new Error('unexpected frame for ' + name + '\n' + compiled)
      const body = lines.slice(4, -4)
      out += '\t\twant: []string{\n' + body.map((l) => `\t\t\t${line(l)},\n`).join('') + '\t\t},\n'
    }
    rows.push(out + '\t},\n')
  }
}
const header = `// Code generated by testdata/record_cases.mjs from edge.js 6.5.1 on Node 24; DO NOT EDIT.

package tags

// compiledPrologue and compiledEpilogue frame every compiled template of the cases.
var compiledPrologue = []string{
${PRE.map((l) => '\t' + goStr(l) + ',\n').join('')}}

var compiledEpilogue = []string{
${POST.map((l) => '\t' + goStr(l) + ',\n').join('')}}

// compileCases are templates compiled the way Edge's compileRaw does, with the
// compiled body between the prologue and the epilogue (stack ids replaced by
// stack_ID), or the error compileRaw throws: "<code> <line>:<col> <message>" for an
// EdgeError, "<name>: <message>" for any other error.
var compileCases = []compileCase{
`
process.stdout.write(header + rows.join('') + '}\n')
